 apply('009-form-one-expansion','0.4.0')
 p=ROOT/'content/library.json';d=json.loads(p.read_text());added=[];by_id={q['id']:i for i,q in enumerate(d['questions'])}
 for lid,items in workbook.items():
  base=next(q for q in d['questions'] if q['topicIds']==[lid])
  for n,(prompt,answer,guide) in enumerate(items,1):
   q={**base,'id':f'{lid}-wb-{n:02}','questionNumber':str(n),'content':prompt,'answerKey':answer,'markingGuide':guide,'type':'short','options':[],'maximumMarks':2,'resourceKind':'workbook','sourceTitle':'SomaSmart original revision workbook','sourceReference':'Original Form One expansion workbook'}
   if q['id'] in by_id:d['questions'][by_id[q['id']]]=q
   else:d['questions'].append(q)
   added.append(q)
 for b in d['books']:
  if b['kind']=='workbook':b['mixedTestQuestionIds']=[q['id'] for q in d['questions'] if q['form']==b['form'] and q['subjectId']==b['subjectId'] and q.get('resourceKind')=='workbook']
 p.write_text(json.dumps(d,ensure_ascii=False,indent=2));(ROOT/'content/batches/010-form-one-workbooks.json').write_text(json.dumps({'questions':added},ensure_ascii=False,indent=2));print('Added',len(added),'separate workbook tasks.')
